<!DOCTYPE html>

<html lang="en"><head><meta charset="utf-8"/><meta content="width=device-width,initial-scale=1" name="viewport"/><title>Luminary · Companion Home</title><link href="/luminary-chat.css?v=recovery-forms-20260726-1" rel="stylesheet"/><link href="/mode-navigation.css?v=polish4" rel="stylesheet"/><link href="/companion/cottage-20261012/style.css?v=polish1" rel="stylesheet"/></head><body class="companion-world-page">
@include('partials.site-header')
<div class="world-toolbar"><button id="chat-toggle">Talk to Luminary</button><a hidden id="studio-link" href="/characters">Edit character</a><button aria-expanded="true" id="panel-toggle">Controls</button></div>
<canvas aria-label="Companion world. Choose Manual Control, then use WASD or arrows to move, Shift to run, and click chairs or the bed to use them. Drag to orbit; scroll to zoom." id="world" role="application" tabindex="0"></canvas>
<aside id="controls"><div class="eyebrow">YOUR COMPANION</div>
<div class="identity-controls"><div><label for="character">Companion</label><select id="character"><option value="luminary">Luminary</option><option value="mira">Mira</option><option value="aurora">Aurora</option></select></div><div><label for="look">Appearance</label><select id="look"><option value="swim">Swimwear</option><option selected="" value="casual">Casual / nice wear</option><option value="gala">Luxury dress</option></select></div></div>
<div aria-label="Avatar control" class="control-switch"><button aria-pressed="true" id="ai-control">AI Control</button><button aria-pressed="false" id="manual-control">Manual Control</button></div>
<select aria-label="Control mode" hidden="" id="control-mode"><option value="ai">AI Control</option><option value="manual">Manual Control</option></select>
<p id="control-status" role="status">Free local routines between chat replies.</p>
<div hidden="" id="manual-actions"><div class="quick-actions"><button id="quick-sit">Sit</button><button id="quick-lie">Lie down</button><button id="quick-stand">Stand</button></div><p>WASD / arrows to move. Shift to run. Click a chair or bed to use it; double-click the floor to walk there.</p></div>
<button id="pause-movement">Pause movement</button>
<details id="advanced-controls"><summary>More options</summary><div class="rule"></div><div class="eyebrow">EXPLORE THE HOME</div><label for="destination">Go to</label><div class="inline"><select id="destination"><option value="living">Living room</option><option value="kitchen">Kitchen</option><option value="study">Study</option><option value="bathroom">Bathroom</option><option value="dining">Dining room</option><option value="bedroom">Bedroom</option><option value="terrace">Terrace</option></select><button id="go">Go</button></div><label for="gait">Movement</label><select id="gait"><option value="walk">Walk</option><option value="run">Run</option></select><div class="pair"><button id="stop">Stop</button><button id="reset">Reset positions</button></div><div class="pair"><button id="face">Face me</button></div>
<div class="rule"></div><div class="eyebrow">REST &amp; RELAX</div><label for="furniture">Furniture</label><select id="furniture"></select><div class="pair"><button id="use-furniture">Sit / lie down</button><button id="stand-up">Stand up</button></div><p id="rest-status" role="status">Click a chair or the bed in Manual Control, or ask in chat.</p><div class="rule"></div><label for="camera">Camera</label><select id="camera"><option value="follow">Follow selected character</option><option value="overview">House overview</option><option value="portrait">Character close-up</option><option value="front">Full body</option></select><label for="lighting">Lighting</label><select id="lighting"><option value="day">Daylight</option><option value="evening">Evening</option></select><label class="check"><input checked="" id="cutaway" type="checkbox"/> Cutaway walls</label><label class="check"><input checked="" id="shadows" type="checkbox"/> Soft shadows</label>
<div aria-label="Movement buttons" id="dpad"><button aria-label="Move forward" data-move="forward">↑</button><div><button aria-label="Move left" data-move="left">←</button><button aria-label="Move backward" data-move="back">↓</button><button aria-label="Move right" data-move="right">→</button></div></div>
</details><p id="house-loading" role="status">Loading textured interior…</p><p id="loading" role="status">Preparing home…</p><div id="loads"></div><p id="error" role="alert"></p><button hidden="" id="retry">Retry selected appearance</button></aside>
<div aria-label="Furniture interactions" id="interaction-markers"></div><button class="interaction-prompt" hidden="" id="interact"></button><div id="hud"><strong id="active-name">Luminary</strong><span id="movement-status">Loading companions…</span><span id="performance"></span></div><div aria-hidden="true" id="room-labels"></div><div aria-label="Characters in the house" id="labels"></div>
<section aria-label="Companion conversation" id="chat-panel"><div class="chat-head"><div><div class="eyebrow">COMPANION MODE</div><h2 id="chat-name">Luminary</h2></div><button aria-label="Close conversation" id="chat-close">×</button></div><label for="chat-model">Conversation model</label><select id="chat-model"><option value="">Account default</option></select><p id="connection">Connecting to your account…</p><div aria-live="polite" id="conversation" role="log"></div><form id="chat-form"><label for="message">Message</label><textarea id="message" maxlength="4000" placeholder="Talk, or ask her to go to the kitchen…" required="" rows="2"></textarea><p class="input-hint">Enter to send · Shift+Enter for a new line</p><button id="send" type="submit">Send</button></form><p class="chat-foot">Saved with this character. Chat Mode and Companion Mode share history and enabled memory. Idle routines and manual reactions make no AI calls.</p><a href="/chats" id="full-chat" rel="noopener" target="_blank">Open saved chats ↗</a><a hidden="" href="/login" id="sign-in" rel="noopener" target="_blank">Sign in to talk ↗</a><button id="reconnect" type="button">Reconnect account</button></section>
<section aria-label="Choose your companion" hidden="" id="companion-picker"><h1>Choose your companion</h1><p>A separate home and saved conversation for each character.</p><div><button data-choose="luminary">Luminary · black hair</button><button data-choose="mira">Mira · brown hair</button><button data-choose="aurora">Aurora · platinum hair</button></div></section><script src="/companion/cottage-20261012/app.js?v=polish2" type="module"></script><script defer src="/mode-navigation.js?v=polish5"></script></body></html>
